<script setup lang="ts">import type{AdminServiceHealth}from"~/composables/useAdminControlPlane";defineProps<{items:AdminServiceHealth[]}>();const labels={ok:"سالم",degraded:"کند",down:"قطع"};</script><template><section class="admin-panel"><header><div><h2>سلامت سرویس‌ها</h2><p>آخرین Heartbeat و بودجه دسترس‌پذیری</p></div><span class="status-pill status-ok">پایش زنده</span></header><div class="service-health-list"><article v-for="item in items" :key="item.service"><span class="service-state" :data-state="item.status"/><div><b>{{item.service}}</b><small>نسخه {{item.version}}</small></div><strong>{{labels[item.status]}}</strong><span>{{item.latency_ms.toLocaleString('fa-IR')}} ms</span><span>{{(item.availability_bps/100).toLocaleString('fa-IR')}}٪</span></article></div></section></template>
